from collections import deque
def transform(g):
    h,w=len(g),len(g[0]); out=[row[:] for row in g]; seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j] and not seen[i][j]:
                comp=[]; q=deque([(i,j)]); seen[i][j]=True
                while q:
                    r,c=q.popleft(); comp.append((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=r+dr,c+dc
                            if 0<=nr<h and 0<=nc<w and not seen[nr][nc] and g[nr][nc]:
                                seen[nr][nc]=True; q.append((nr,nc))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                layers={}
                for r,c in comp:
                    L=min(r-r0,r1-r,c-c0,c1-c)
                    layers.setdefault(g[r][c],L)
                    layers[g[r][c]]=min(layers[g[r][c]],L)
                order=sorted(layers,key=lambda k:layers[k]); rev=order[::-1]
                mp=dict(zip(order,rev))
                for r,c in comp: out[r][c]=mp[g[r][c]]
    return out
